// Generated from sw5e_source_complete/weaponProperty.json, armorProperty.json, weaponFocus.json, weaponSupremacy.json
const SW5E_WEAPON_PROPERTIES = [{"name":"Auto","description":"Weapons with this property can only fire in burst, penetrating, or rapid modes. If the weapon has any combination of burst, penetrating, and rapid modes, you choose which mode to use. You can only use one mode at a time.","effects":[{"type":"weaponRule","kind":"fireModeRestriction","params":{"modes":["burst","penetrating","rapid"]}}]},{"name":"Biting","description":"This weapon's damage becomes acid. Additionally, when you would make a melee weapon attack with a weapon with the biting property, you can instead force the target to make a Constitution saving throw (DC = 8 + your bonus to attacks with the weapon, or the biting number, whichever is lower). If you would have advantage on your attack roll, the creature instead has disadvantage on their saving throw, and if you would have disadvantage on your attack roll, the creature instead has advantage on their saving throw. On a failed save, the target takes normal weapon damage and is subjected to any additional effects that would occur on a hit, and the first attack it makes before the end of its next turn has disadvantage. If damage dealt by this weapon reduces a creature to 0 hit points, it must make a DC 13 Constitution saving throw. On a failed save, it dies immediately without making death saving throws. A disintegrated creature and everything unenhanced it is wearing and carrying are reduced to a pile of fine gray dust. A creature destroyed in this way can not be revitalized.","effects":[{"type":"weaponRule","kind":"saveConversion","params":{"damageType":"acid","saveAbility":"Constitution","dcCap":"$param","invertRollMode":true,"onFailure":{"normalDamage":true,"onHitEffects":true,"effect":"firstAttackDisadvantage"}},"durationSpec":{"anchor":"endOfTargetNextTurn"}},{"type":"weaponRule","kind":"hitOutcome","params":{"trigger":"reducesToZero","saveAbility":"Constitution","dc":13,"failure":"Dies immediately without death saves. The creature and its unenhanced gear turn to dust. The creature cannot be revitalized."}}]},{"name":"Bright","description":"This weapon's damage becomes fire, and its luminous property sheds bright light in a 5-foot radius and dim light for an additional 5 feet while activated, instead of only dim light in a 5-foot radius. Additionally, when you would make a melee weapon attack with a weapon with the bright property, you can instead force the target to make a Dexterity saving throw (DC = 8 + your bonus to attacks with the weapon, or the bright number, whichever is lower). If you would have advantage on your attack roll, the creature instead has disadvantage on their saving throw, and if you would have disadvantage on your attack roll, the creature instead has advantage on their saving throw. On a failed save, the target takes normal weapon damage and is subjected to any additional effects that would occur on a hit, and the creature takes additional damage of the same type at the start of its next turn equal to your governing ability modifier.","effects":[{"type":"weaponRule","kind":"saveConversion","params":{"damageType":"fire","saveAbility":"Dexterity","dcCap":"$param","invertRollMode":true,"onFailure":{"normalDamage":true,"onHitEffects":true,"effect":"governingAbilityDamage"}},"durationSpec":{"anchor":"startOfTargetNextTurn"},"turnTriggers":[{"timing":"startOfTurn","actor":"target","kind":"damage","formula":"{weaponAbilityMod}","note":"Take fire damage equal to the attacker's governing ability modifier."}]},{"type":"weaponRule","kind":"lightOverride","params":{"bright":5,"dim":5}}]},{"name":"Brutal","description":"When you score a critical hit with a weapon with the brutal property, you roll a number of additional weapon damage dice equal to the brutal number.","effects":[{"type":"critMod","brutalDice":"$param"}]},{"name":"Burst","description":"When you would make a ranged weapon attack with a weapon with this property, you can instead spray a 10-foot-cube area within range with shots, consuming ammunition equal to the burst number. Each creature in the area must make a Dexterity saving throw (DC = 8 + your bonus to attacks with the weapon) or take the weapon's normal damage. Before you use this property, you can declare one creature that would be affected by it. If the creature fails its save, in addition to the weapon's normal damage, it is subjected to any additional effects that would occur on a hit. If you would have advantage on your attack roll, the creature instead has disadvantage on their saving throw, and if you would have disadvantage on your attack roll, the creature instead has advantage on their saving throw.","effects":[{"type":"weaponRule","kind":"fireMode","params":{"mode":"burst","ammoCost":"$param","area":{"shape":"cube","size":10},"saveAbility":"Dexterity","onFailure":{"normalDamage":true},"declaredTarget":{"count":1,"onHitEffects":true,"invertRollMode":true}}}]},{"name":"Corruption","description":"This weapon's damage becomes necrotic, and it loses the luminous property if it has it. Additionally, when you would make a melee weapon attack with a weapon with the corruption property, you can instead force the target to make a Wisdom saving throw (DC = 8 + your bonus to attacks with the weapon, or the corruption number, whichever is lower). If you would have advantage on your attack roll, the creature instead has disadvantage on their saving throw, and if you would have disadvantage on your attack roll, the creature instead has advantage on their saving throw. On a failed save, the target takes normal weapon damage and is subjected to any additional effects that would occur on a hit, and the creature cannot regain hit points until the start of your next turn.","effects":[{"type":"weaponRule","kind":"saveConversion","params":{"damageType":"necrotic","saveAbility":"Wisdom","dcCap":"$param","invertRollMode":true,"onFailure":{"normalDamage":true,"onHitEffects":true,"effect":"preventHealing"}},"durationSpec":{"anchor":"startOfSourceNextTurn"}},{"type":"weaponRule","kind":"lightOverride","params":{"suppress":true}}]},{"name":"Defensive","description":"When you make your first attack on your turn with a weapon with the defensive property, you can choose to suffer a penalty to attack and damage rolls with that weapon up to the defensive number. If you do so, you gain the same bonus to AC. These effects last until the start of your next turn, as long as you're holding the weapon.","effects":[{"type":"attackDamageMod","scope":"weapon","tradeoff":{"kind":"defensive","maxPenalty":"$param","trigger":"firstOwnTurnAttack"},"durationSpec":{"anchor":"startOfOwnNextTurn"},"cadence":"oncePerTurn"}]},{"name":"Dexterity","description":"A weapon with this property requires more skill to control. While wielding it, you have disadvantage on attack rolls unless you meet the Dexterity requirement.","effects":[{"type":"weaponRule","kind":"abilityReq","params":{"ability":"Dexterity","minScore":"$param"}}]},{"name":"Dire","description":"Before you make a weapon attack with a weapon with the dire property, you can choose to suffer a penalty to the attack roll up to the dire number. If you do so and you hit with it, you gain an equivalent bonus to the damage roll.","effects":[{"type":"attackDamageMod","scope":"weapon","tradeoff":{"kind":"dire","maxPenalty":"$param","trigger":"beforeAttack"},"durationSpec":{"anchor":"instant"}}]},{"name":"Disarming","description":"When you score a critical hit with a weapon with the disarming property against a creature that is holding an object, you can attempt to disarm the target (no action required). If the target is no more than one size larger than you (your size or smaller if your weapon has the light property), it must succeed on a Strength saving throw (DC = 8 + your bonus to attacks with the weapon) or it drops an object of your choice at its feet.","effects":[{"type":"weaponRule","kind":"hitOutcome","params":{"trigger":"criticalHit","optional":true,"requiresHeldObject":true,"maxSizeDifference":1,"lightMaxSizeDifference":0,"saveAbility":"Strength","dcBonus":8,"failure":"Drops an object of your choice at its feet."}}]},{"name":"Disguised","description":"You have advantage on Charisma (Deception) checks made to hide the nature of a weapon with this property.","effects":[{"type":"conditionalCheckMod","skills":["Deception"],"mode":"advantage","condition":"hiding the nature of a disguised weapon","groupPropertySources":true,"when":{"carried":true}}]},{"name":"Disintegrate","description":"When a creature is reduced to 0 hit points by a weapon with the disintegrate property, it must make a Constitution saving throw, DC equal to the disintegrate number. On a failed save, it dies immediately without making death saving throws. A disintegrated creature and everything unenhanced it is wearing or carrying are reduced to a pile of fine gray dust. A creature destroyed in this way can not be revitalized.","effects":[{"type":"weaponRule","kind":"hitOutcome","params":{"trigger":"reducesToZero","saveAbility":"Constitution","dc":"$param","failure":"Dies immediately without death saves. The creature and its unenhanced gear turn to dust. The creature cannot be revitalized."}}]},{"name":"Disruptive","description":"When a creature is forced to make a Constitution saving throw to maintain concentration due to taking damage from a weapon with the disruptive property, the DC for the check equals 10 or the full damage taken, whichever number is higher, instead of only half.","effects":[{"type":"weaponRule","kind":"hitOutcome","params":{"trigger":"concentrationSave","saveAbility":"Constitution","dcFloor":10,"damageMultiplier":1}}]},{"name":"Double","description":"A weapon with this property can be used with one or two hands. A damage value in parentheses appears with the property—the damage when the weapon is used with Double-Weapon Fighting. See the rules for Double-Weapon Fighting in chapter 9.","effects":[{"type":"weaponRule","kind":"doubleWeapon","params":{"offhandDamage":"$paren"}}]},{"name":"Finesse","description":"When making an attack with a weapon with this property, you use your choice of your Strength or Dexterity modifier for the attack and damage rolls. You must use the same modifier for both rolls.","effects":[{"type":"weaponRule","kind":"abilityChoice","params":{"abilities":["Strength","Dexterity"],"mode":"finesse"}}]},{"name":"Fixed","description":"A weapon with this property does not fill the hand, but you can't use the weapon while the hand is full. Additionally, you have a +10 bonus to ability checks and saving throws to avoid being disarmed of this weapon.","effects":[{"type":"weaponRule","kind":"fixedGrip","params":{"occupiesHands":0,"requiresFreeHand":true}},{"type":"conditionalCheckMod","skills":"all","mode":"bonus","value":10,"condition":"avoiding being disarmed of a fixed weapon","groupPropertySources":true},{"type":"saveMod","abilities":"all","mode":"bonus","value":10,"condition":"avoiding being disarmed of a fixed weapon","groupPropertySources":true}]},{"name":"Heavy","description":"When you hit with an attack roll using Strength with a weapon with this property, you deal additional damage equal to half your Strength modifier (minimum of +1).","effects":[{"type":"weaponRule","kind":"heavy"},{"type":"attackDamageMod","scope":"weapon","extraDamageFormula":"max(1, floor(STR_mod / 2))","condition":"attack roll using Strength"}]},{"name":"Hidden","description":"You have advantage on Dexterity (Sleight of Hand) checks made to conceal a weapon with this property.","effects":[{"type":"conditionalCheckMod","skills":["Sleight of Hand"],"mode":"advantage","condition":"concealing a hidden weapon","groupPropertySources":true,"when":{"carried":true}}]},{"name":"Interlocking","description":"While wielding a weapon with the interlocking property, you can use your object interaction to detach the weapon into two separate weapons or reattach into a single weapon. While separated, each weapon has the same damage, damage type, combined value and weight, and properties (except for the double property) as the single weapon.","effects":[{"type":"weaponRule","kind":"interlocking","params":{"removesProperties":["double"]}}]},{"name":"Keen","description":"When you make a weapon attack with a weapon with the keen property, the critical hit range increases by an amount equal to the keen number.","effects":[{"type":"critMod","critRangeDelta":"$param"}]},{"name":"Light","description":"A weapon with this property is small and easy to handle, making it ideal for use when engaging in Double- or Two-Weapon Fighting. See the rules for Double- and Two-Weapon Fighting in chapter 9.","effects":[{"type":"weaponRule","kind":"light","params":{"enablesTWF":true,"enablesDWF":true}}]},{"name":"Luminous","description":"A weapon with this property sheds dim light in a 5-foot radius while activated. Additionally, Dexterity (Stealth) checks made while the weapon is activated have disadvantage.","effects":[{"type":"weaponRule","kind":"illumination","params":{"bright":0,"dim":5}},{"type":"conditionalCheckMod","skills":["Stealth"],"mode":"disadvantage","condition":"while luminous weapon is activated","groupPropertySources":true}]},{"name":"Mighty","description":"When making an attack with a mighty weapon, you use your choice of your Strength or Dexterity modifier for the attack and damage rolls. You must use the same modifier for both rolls.","effects":[{"type":"weaponRule","kind":"abilityChoice","params":{"abilities":["Strength","Dexterity"],"mode":"mighty"}}]},{"name":"Modal","description":"A weapon with this property can switch between modes. A list of weapons in parentheses appears with the property-the weapons between which an exotic weapon can be switched by using an object interaction.","effects":[{"type":"weaponRule","kind":"modal","params":{"modes":"$paren"}}]},{"name":"Neuralizing","description":"When you hit a creature with a weapon with the neuralizing property, you can force it to make a Wisdom saving throw, DC equal to the neuralizing number. On a failed save, the creature takes an additional 1d4 psychic damage and becomes frightened of you until the start of its next turn.","effects":[{"type":"weaponRule","kind":"hitOutcome","params":{"trigger":"onHit","optional":true,"saveAbility":"Wisdom","dc":"$param","extraDamage":"1d4 psychic","condition":"frightened","duration":"until the start of its next turn","conditionOfSource":true},"durationSpec":{"anchor":"startOfTargetNextTurn"}}]},{"name":"Penetrating","description":"When you would make a ranged weapon attack with a weapon with this property, you can instead attempt to penetrate and hit a creature behind the target, consuming ammunition equal to the penetrating number. Make an attack roll against the initial target. If the attack hits, there is a creature within 15 feet of that creature and directly behind it, and the original attack roll would hit the second creature, it also takes normal weapon damage. Alternatively, you can use this property to fire at a creature through partial cover. When you do so, you reduce the target's cover by one step (from three-quarters to half or half to one-quarter), rather than targeting a second creature.","effects":[{"type":"weaponRule","kind":"fireMode","params":{"mode":"penetrating","ammoCost":"$param","penetrateDistance":15,"coverReductionSteps":1}}]},{"name":"Piercing","description":"Before you make a weapon attack with a weapon with the piercing property, you can choose to gain a bonus to the attack roll up to the piercing number. If you do so and you hit with it, you suffer an equivalent penalty to the damage roll.","effects":[{"type":"attackDamageMod","scope":"weapon","tradeoff":{"kind":"piercing","maxBonus":"$param","trigger":"beforeAttack"},"durationSpec":{"anchor":"instant"}}]},{"name":"Power Cell","description":"Weapons with this property are fueled by power cells, which must be loaded in order to fire the weapon. A power cell fuels a number of attacks equal to the weapon's reload number.","effects":[{"type":"weaponRule","kind":"ammunition","params":{"ammoType":"power cell","range":"$paren"}}]},{"name":"Range","description":"A weapon that can be used to make a ranged attack has this property. The range lists two numbers. The first is the weapon's normal range in feet, and the second indicates the weapon's long range. When attacking a target beyond normal range, you have disadvantage on the attack roll. You can't attack a target beyond the weapon's long range.","effects":[{"type":"weaponRule","kind":"range","params":{"range":"$paren","longRangeDisadv":true}}]},{"name":"Rapid","description":"When you would make a ranged weapon attack with a weapon with this property, you can instead unload on a single target, consuming ammunition equal to the rapid number. The target must make a Dexterity saving throw (DC = 8 + your bonus to attacks with the weapon). On a failed save, roll the weapon's damage dice twice and add them together, adding relevant modifiers as normal and subjecting the target to any additional effects that would occur on a hit. If you would have advantage on your attack roll, the creature instead has disadvantage on their saving throw, and if you would have disadvantage on your attack roll, the creature instead has advantage on their saving throw.","effects":[{"type":"weaponRule","kind":"fireMode","params":{"mode":"rapid","ammoCost":"$param","saveAbility":"Dexterity","invertRollMode":true,"onFailure":{"diceMultiplier":2,"onHitEffects":true}}}]},{"name":"Reach","description":"A weapon with this property adds 5 feet to your reach with it.","effects":[{"type":"weaponRule","kind":"reach","params":{"bonusFeet":5}}]},{"name":"Reckless","description":"When you make your first attack on your turn with a weapon with the reckless property, you can choose to gain a penalty to AC up to the reckless number. If you do so, you gain the same bonus to attack and damage rolls with that weapon. These effects last until the start of your next turn, as long as you're holding the weapon.","effects":[{"type":"attackDamageMod","scope":"weapon","tradeoff":{"kind":"reckless","maxPenalty":"$param","trigger":"firstOwnTurnAttack"},"durationSpec":{"anchor":"startOfOwnNextTurn"},"cadence":"oncePerTurn"}]},{"name":"Reload","description":"A number of shots equal to the reload number can be made with a weapon with this property. A character must then reload it using an action or a bonus action (their choice). You must have one free hand to reload.","effects":[{"type":"weaponRule","kind":"reload","params":{"shots":"$param","reloadCost":"action or bonus action (1 free hand)"}}]},{"name":"Returning","description":"When you throw a weapon with this property, it automatically returns to your hand after the attack is complete, whether you hit or miss.","effects":[{"type":"weaponRule","kind":"returning","params":{"autoReturn":true}}]},{"name":"Shocking","description":"When you hit a creature with a weapon with the shocking property, you can force it to make a Dexterity saving throw, DC equal to the shocking number. On a failed save, the creature takes an additional 1d4 lightning damage and becomes shocked until the end of its next turn.","effects":[{"type":"weaponRule","kind":"hitOutcome","params":{"trigger":"onHit","optional":true,"saveAbility":"Dexterity","dc":"$param","extraDamage":"1d4 lightning","condition":"shocked","duration":"until the end of its next turn"},"durationSpec":{"anchor":"endOfTargetNextTurn"}}]},{"name":"Silent","description":"When you make a ranged weapon attack with a weapon with the silent property while hidden, it does not automatically reveal your presence. Make a Dexterity (Stealth) check contested by your targets' Wisdom (Perception) check. On a success, you remain hidden.","effects":[{"type":"weaponRule","kind":"silent","params":{"contestedCheck":"Dexterity (Stealth) vs. Wisdom (Perception)"}},{"type":"conditionalCheckMod","skills":["Stealth"],"mode":"bonus","value":0,"condition":"remaining hidden after a ranged attack with a silent weapon (contested by target's Perception)"}]},{"name":"Slug Cartridge","description":"Weapons with this property fire slug cartridges, which must be loaded in order to fire the weapon.","effects":[{"type":"weaponRule","kind":"ammunition","params":{"ammoType":"slug cartridge","range":"$paren"}}]},{"name":"Smart","description":"This weapon ignores your Dexterity score and proficiency bonus. Two numbers appear in parentheses with the property—the first is the weapon's Dexterity score, and the second is the weapon's proficiency bonus. The weapon uses these values instead of yours when you make attack and damage rolls with it. If you lack proficiency with the weapon, the weapon does not benefit from its proficiency bonus.","effects":[{"type":"weaponRule","kind":"smartStats","params":{"values":"$paren","note":"Uses weapon's (DEX, PB) instead of yours for attack/damage; loses weapon PB if not proficient."}}]},{"name":"Sonorous","description":"When you hit a creature with a weapon with the sonorous property, you can force it to make a Constitution saving throw, DC equal to the sonorous number. On a failed save, the creature takes an additional 1d4 sonic damage and becomes deafened until the end of its next turn.","effects":[{"type":"weaponRule","kind":"hitOutcome","params":{"trigger":"onHit","optional":true,"saveAbility":"Constitution","dc":"$param","extraDamage":"1d4 sonic","condition":"deafened","duration":"until the end of its next turn"},"durationSpec":{"anchor":"endOfTargetNextTurn"}}]},{"name":"Special","description":"A weapon with this property has unusual rules governing its use, explained in the weapon's description (see \"Special Weapons\" later in this section).","effects":[{"type":"weaponRule","kind":"special","params":{"range":"$paren"}},{"type":"contextualNote","surface":"attacks","title":"Special Weapon","text":"Has unusual rules defined in the weapon's own description."}]},{"name":"Specialized","description":"A weapon with this property bypasses the base and cap of certain properties. Another weapon property in parentheses with the property-the weapon property that the exotic bypasses the base and cap for.","effects":[{"type":"weaponRule","kind":"specialized","params":{"bypassesProperty":"$paren"}}]},{"name":"Strength","description":"A weapon with this property has a heavy kickback. While wielding it, you have disadvantage on attack rolls unless you meet the Strength requirement. If the weapon has the burst, penetrating, or rapid property, you must meet the Strength requirement to use this feature. If the weapon lacks the two-handed property, you can wield the weapon in two hands to temporarily reduce the strength number by one step (from 19 to 17, 17 to 15, 15 to 13, or 13 to 11). If this would reduce the strength number below 11, you ignore it entirely.","effects":[{"type":"weaponRule","kind":"abilityReq","params":{"ability":"Strength","minScore":"$param","penalty":"disadvantage on attacks and cannot use burst/penetrating/rapid; two-handing non-two-handed reduces req by 1 step (ignore below 11)","blocksFireModes":["burst","penetrating","rapid"]}}]},{"name":"Switch","description":"A weapon with the switch property can deal an alternate type of damage. A damage value appears in parentheses appears with the property-the damage when the weapon uses its alternate damage type. On your turn, you can use your object interaction to change the weapon's damage type.","effects":[{"type":"weaponRule","kind":"switch","params":{"alternateDamage":"$paren"}},{"type":"actionGrant","zone":"special","name":"Switch Damage Type","summary":"Object interaction: switch weapon to alternate damage ($paren)."}]},{"name":"Thrown","description":"Weapons with this property can be thrown to make a ranged attack. If the weapon would normally be used to make melee weapon attacks, you use the same ability modifier for that attack roll and damage roll that you would use for a melee attack with the weapon.","effects":[{"type":"weaponRule","kind":"thrown","params":{"usesMeleeAbility":true,"range":"$paren"}}]},{"name":"Two-Handed","description":"A weapon with this property requires two hands to use.","effects":[{"type":"weaponRule","kind":"twoHanded","params":{"hands":2}}]},{"name":"Versatile","description":"A weapon with this property can be used with one or two hands. A damage value in parentheses appears with the property—the damage when the weapon is used with two hands to make a melee attack.","effects":[{"type":"weaponRule","kind":"versatile","params":{"twoHandedDamage":"$paren"}}]},{"name":"Vicious","description":"Whenever you deal damage with a weapon with the vicious property and roll the maximum on a weapon damage die, you gain a bonus to damage equal to the vicious number.","effects":[{"type":"attackDamageMod","scope":"weapon","viciousBonusOnMaxDie":"$param"}]}];
const SW5E_ARMOR_PROPERTIES = [{"name":"Absorptive","description":"When you are wearing armor or wielding a shield with this property, damage that you take from weapons is reduced by an amount equal to the absorptive number. If this would reduce the damage to 0, the damage is instead reduced to 1.","effects":[{"type":"damageReduction","amount":"$param","damageTypes":["weapon"],"minDamage":1}],"appliesTo":"both","defaultParam":1},{"name":"Agile","description":"While wearing armor or wielding a shield with this property, your Dexterity score becomes equal to the agile number. If your Dexterity is already equal to or greater than the agile number, it has no effect on you.","effects":[{"type":"abilityFloor","ability":"Dexterity","floor":"$param"}],"appliesTo":"both"},{"name":"Anchor","description":"A shield with this property can be used to provide cover. As an action, you can anchor or recover the shield. While anchored, you gain no benefit from a shield, and it does not require the use of a hand. Instead, while anchored, a light shield provides one-quarter cover, a medium shield provides half cover, and a heavy shield provides three-quarters cover.","effects":[{"type":"actionGrant","zone":"action","name":"Anchor / Recover Shield","summary":"Action: anchor or recover shield. While anchored, no shield AC or hand required; light/medium/heavy shield provides 1/4, 1/2, or 3/4 cover.","cadence":"unlimited"}],"appliesTo":"shield"},{"name":"Avoidant","description":"When wearing armor or wielding a shield with this property and a creature makes an attack against you, the critical hit range decreases by an amount equal to the avoidant number, to a minimum of 1.","effects":[{"type":"combatTrait","kind":"incomingCritReduction","value":"$param","note":"Attackers' critical hit range against you decreases by $param (minimum 1)"}],"appliesTo":"both","defaultParam":1},{"name":"Barbed","description":"When you succeed on a Strength (Athletics) check to initiate or maintain a grapple while wearing armor with this property, the creature takes kinetic damage using the barbed damage (which appears in parentheses with the property) + your Strength modifier.","effects":[{"type":"contextualNote","surface":"attacks","title":"Barbed Armor","text":"When you succeed on a Strength (Athletics) check to initiate or maintain a grapple, the target takes $paren + your Strength modifier ({strMod}) kinetic damage."}],"appliesTo":"armor","defaultParen":"1d4"},{"name":"Bulky","description":"While wearing armor with this property, you have disadvantage on Dexterity (Stealth) checks that rely on sound.","effects":[{"type":"conditionalCheckMod","skills":["Stealth"],"mode":"disadvantage","condition":"relying on sound"}],"appliesTo":"armor"},{"name":"Charging","description":"When you take damage while wearing armor or wielding a shield with this property, you gain a charge. You can store a maximum number of charges equal to the charging number, and the charges last for 1 minute. The next time you hit with a melee weapon attack while you have charges, you deal additional damage of the same type as the weapon's damage equal to the number of charges stored, and the charges are expended.","effects":[{"type":"resourcePool","id":"armor_charging","name":"Charging Charges","max":"$param","recharge":"trigger","rechargeNote":"Gain 1 charge when taking damage (lasts 1 min); expend on next melee weapon hit for +1 same-type damage per charge."}],"appliesTo":"both","defaultParam":1},{"name":"Concealing","description":"While wielding a shield with this property, you have advantage on Dexterity (Stealth) checks that rely on sight.","effects":[{"type":"conditionalCheckMod","skills":["Stealth"],"mode":"advantage","condition":"relying on sight"}],"appliesTo":"shield"},{"name":"Cumbersome","description":"While wearing armor or wielding a shield with this property, your speed is reduced by 5.","effects":[{"type":"speed","mode":"walk","bonus":-5}],"appliesTo":"both"},{"name":"Gauntleted","description":"While wearing armor with this property, your unarmed strikes deal kinetic damage using the gauntleted damage (which appears in parentheses with the property) + your Strength modifier.","effects":[{"type":"weaponRule","kind":"unarmedDie","params":{"die":"$paren","damageType":"kinetic","ability":"Strength"}}],"appliesTo":"armor","defaultParen":"1d4"},{"name":"Imbalanced","description":"When you are critically hit while wielding a shield with this property, you can't take reactions until the start of your next turn, and you gain no AC benefit from your shield against the next attack against you before the start of your next turn.","effects":[{"type":"contextualNote","surface":"defenses","title":"Imbalanced Shield","text":"When critically hit, you cannot take reactions until the start of your next turn and gain no shield AC against the next attack before then."}],"appliesTo":"shield"},{"name":"Impermeable","description":"Armor with this property includes the limited functions of a number of enviromental suits equal the impermeable number from the list below, which are either included in parentheses with the property or determined by the GM. Additionally, it includes 4 hours' capacity of oxygen, which can be replenished by oxygen tanks.\n- **Chemical Suit:** You are immune to the corroded condition.\n- **Conductive Suit:** You are immune to the shocked condition.\n- **Dampening Suit:** You are immune to the deafened condition, and you can't have disadvantage on Wisdom (Perception) and Intelligence (Investigation) checks that rely on sound.\n- **Diving Suit:** You are protected from the hazards associated with high pressure environments.\n- **Flame-Proof Suit:** You are immune to the ignited condition.\n- **Hazard Suit:** You are immune to the poisoned condition.\n- **Mind-Shielding Suit:** You have advantage on saving throws to avoid being frightened, and you have advantage on saving throws to avoid having your mind read or affected.\n- **Space Suit:** You are protected from the hazards associated with low pressure environments.\n- **Stabilizer Suit:** You have advantage on ability checks and saving throws to avoid being moved.","effects":[{"type":"contextualNote","surface":"defenses","title":"Impermeable Environmental Suit","text":"Includes $param GM-chosen environmental suit function(s) plus 4 hours oxygen capacity."}],"appliesTo":"armor","defaultParam":1,"suitEffects":{"chemical":[{"type":"conditionImmunity","condition":"Corroded","mode":"immune"}],"conductive":[{"type":"conditionImmunity","condition":"Shocked","mode":"immune"}],"dampening":[{"type":"conditionImmunity","condition":"Deafened","mode":"immune"},{"type":"conditionalCheckMod","skills":["Perception","Investigation"],"mode":"note","condition":"cannot have disadvantage on checks relying on sound"}],"diving":[{"type":"contextualNote","surface":"defenses","title":"Diving Suit","text":"Protected from hazards associated with high-pressure environments."}],"flame":[{"type":"conditionImmunity","condition":"Ignited","mode":"immune"}],"hazard":[{"type":"conditionImmunity","condition":"Poisoned","mode":"immune"}],"mind":[{"type":"saveMod","abilities":["all"],"mode":"advantage","condition":"to avoid being frightened or having your mind read or affected"}],"space":[{"type":"contextualNote","surface":"defenses","title":"Space Suit","text":"Protected from hazards associated with low-pressure environments."}],"stabilizer":[{"type":"saveMod","abilities":["all"],"mode":"advantage","condition":"to avoid being moved"},{"type":"conditionalCheckMod","skills":["Athletics","Acrobatics"],"mode":"advantage","condition":"to avoid being moved"}]}},{"name":"Insulated","description":"When you make a saving throw against an effect that would deal ion or lightning damage while wearing armor or wielding a shield with this property, you can treat a d20 roll of below the insulated number as the insulated number.","effects":[{"type":"rollFloor","scope":"save","minRoll":"$param","condition":"saving throws against effects dealing ion or lightning damage"}],"appliesTo":"both"},{"name":"Interlocking","description":"While wielding a shield with this property within 5 feet of a friendly creature who is also wielding a shield with this property, you can both use your reactions on either of your turns to interlock the shields. While interlocked, both creatures gain a bonus to AC equal to the interlocking number. If at any point the creatures are more than 5 feet from each other, the shields immediately de-interlock, and this effect ends.","effects":[{"type":"actionGrant","zone":"reaction","name":"Interlock Shields","summary":"Reaction while within 5 ft of an ally also wielding an interlocking shield: both gain +$param AC until more than 5 ft apart.","cadence":"unlimited","reactionKind":"standard"}],"appliesTo":"shield","defaultParam":1},{"name":"Lambent","description":"While wielding a shield with this property, you can use a bonus action to activate or deactivate the shield's light. While active, the shield sheds bright light in a 5-foot radius and dim light for an additional 5 feet. Additionally, Dexterity (Stealth) checks made while the shield's light is active that rely on sight have disadvantage.","effects":[{"type":"actionGrant","zone":"bonus","name":"Toggle Lambent Shield Light","summary":"Bonus action: toggle bright light 5 ft + dim light 5 ft. While active, disadvantage on sight-based Stealth checks.","cadence":"unlimited"}],"appliesTo":"shield"},{"name":"Lightweight","description":"Armor and shields with this property have their weight reduced by half.","effects":[{"type":"weightMultiplier","target":"selfItem","multiplier":0.5}],"appliesTo":"both"},{"name":"Magnetic","description":"While you are wielding a shield with this property and a melee weapon attack misses you by an amount less than or equal to your bonus to AC from your shield, the attacking creature must make a Strength check, DC equal to the magnetic number. On a failed save, the creature's weapon adheres to the shield. As an action, a creature can repeat this check. On a success, the weapon is freed.","effects":[{"type":"contextualNote","surface":"defenses","title":"Magnetic Shield","text":"When a melee weapon attack misses by ≤ your shield AC bonus, the attacker makes a DC $param Strength check or its weapon adheres to the shield (action to repeat check to free)."}],"appliesTo":"shield","defaultParam":1},{"name":"Obscured","description":"While wearing armor or wielding a shield with this property, electronic sensors and cameras have disadvantage on Wisdom (Perception) and Intelligence (Investigation) checks against you that rely on sight.","effects":[{"type":"combatTrait","kind":"sensorObscured","note":"Electronic sensors and cameras have disadvantage on sight-based Wisdom (Perception) and Intelligence (Investigation) checks against you"}],"appliesTo":"both"},{"name":"Obtrusive","description":"While wielding a shield with this property, you have disadvantage on Dexterity (Stealth) checks that rely on sight.","effects":[{"type":"conditionalCheckMod","skills":["Stealth"],"mode":"disadvantage","condition":"relying on sight","suppressibleBy":"ignoreObtrusiveShield"}],"appliesTo":"shield"},{"name":"Powered","description":"While wearing armor with this property, your Strength score becomes equal to the powered number. If your Strength is already equal to or greater than the powered number, it has no effect on you.","effects":[{"type":"abilityFloor","ability":"Strength","floor":"$param"}],"appliesTo":"armor"},{"name":"Reactive","description":"When you are wearing armor with this property and a creature hits you with an attack roll, you gain a bonus to AC against the next attack from that creature before the start of your next turn equal to the reactive number.","effects":[{"type":"contextualNote","surface":"defenses","title":"Reactive Armor","text":"When hit by an attack roll, gain +$param AC against the next attack from that creature before the start of your next turn."}],"appliesTo":"armor","defaultParam":1,"defenseSummary":true},{"name":"Regulated","description":"When you are wearing armor or wielding a shield with this property and a creature rolls the maximum on a weapon damage die against you, they must reroll and use the new roll, even if the new roll is the maximum on the weapon damage die.","effects":[{"type":"combatTrait","kind":"regulatedRerollMaxDamage","note":"Attackers rolling maximum on a weapon damage die against you must reroll and use the new roll, even if the new roll is the maximum"}],"appliesTo":"both","defenseSummary":true},{"name":"Reinforced","description":"When you make a long jump while wearing armor with this property, you can cover a number of feet up to twice your Strength score. When you make a high jump, you can leap a number of feet up into the air equal to 3 + twice your Strength modifier.","effects":[{"type":"speed","mode":"walk","note":"Long jump up to 2 × Strength score; high jump up to 3 + 2 × Strength modifier"}],"appliesTo":"armor","defenseSummary":true},{"name":"Responsive","description":"While you are wielding a shield with this property and an attack misses you by an amount less than or equal to your bonus to AC from your shield, you gain a bonus to AC against the next attack from that creature before the start of your next turn equal to the responsive number.","effects":[{"type":"contextualNote","surface":"defenses","title":"Responsive Shield","text":"When an attack misses by ≤ your shield AC bonus, gain +$param AC against the next attack from that creature before the start of your next turn."}],"appliesTo":"shield","defaultParam":1},{"name":"Rigid","description":"While wearing armor with this property, you add half your Dexterity modifier (rounded down), instead of your full Dexterity modifier, to Dexterity saving throws you make. If your Dexterity modifier is negative, you instead subtract the full modifier.","effects":[{"type":"saveMod","abilities":["Dexterity"],"mode":"halfPositiveMod","condition":"half positive Dexterity modifier (rounded down), full negative modifier"}],"appliesTo":"armor"},{"name":"Silent","description":"While wearing armor with this property, you have advantage on Dexterity (Stealth) checks that rely on sound.","effects":[{"type":"conditionalCheckMod","skills":["Stealth"],"mode":"advantage","condition":"relying on sound"}],"appliesTo":"armor","defenseSummary":true},{"name":"Spiked","description":"When you succeed on a Strength (Athletics) check to shove or trip a creature while wielding a shield with this property, the creature takes kinetic damage using the spiked damage (which appears in parentheses with the property) + your Strength modifier. If you use a shield with this property as an improvised weapon, the damage increases by one step (from d4 to d6, d6 to d8, or d8 to 2d4).","effects":[{"type":"contextualNote","surface":"attacks","title":"Spiked Shield","text":"On a successful Strength (Athletics) check to shove or trip, target takes $paren + your Strength modifier ({strMod}) kinetic damage; improvised shield damage increases by one die step."}],"appliesTo":"shield","defaultParen":"1d4","defenseSummary":true},{"name":"Steadfast","description":"While wearing armor or wielding a shield with this property, you have advantage on Strength checks and Strength saving throws to avoid being moved.","effects":[{"type":"conditionalCheckMod","ability":"Strength","mode":"advantage","condition":"avoiding being moved"},{"type":"saveMod","abilities":["Strength"],"mode":"advantage","condition":"avoiding being moved"}],"appliesTo":"both"},{"name":"Strength","description":"While wearing armor or wielding a shield with this property, your speed is reduced by 10 unless your Strength score meets or exceeds the strength number.","effects":[{"type":"weaponRule","kind":"abilityReq","params":{"ability":"Strength","minScore":"$param","penalty":"speed −10 ft"}}],"appliesTo":"both"},{"name":"Versatile","description":"A shield with this property can be used with one or two hands. While wielded in two hands, you gain an additional bonus to AC equal to the versatile number.","effects":[{"type":"acBonus","value":"$param","condition":"wielded in two hands"}],"appliesTo":"shield","defaultParam":1}];
const SW5E_WEAPON_FOCUSES = [{"name":"Blade Focus","group":"Blade","source":"Wretched Hives","description":"You've focused your combat training on blade weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's damage rolls.\n- When you score a critical hit with the weapon, the next attack roll the target makes before the start of your next turn has disadvantage.\n- When you take the Attack action, you can choose to forgo one or more attacks to **parry**. For each attack you forgo, you gain a +1 bonus to AC until the start of your next turn.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"blade","damageBonus":1,"when":{"proficient":true}},{"type":"contextualNote","surface":"attacks","title":"Blade Focus (Critical Hit)","text":"On a critical hit with a proficient blade weapon, the target's next attack roll before the start of your next turn has disadvantage.","durationSpec":{"anchor":"startOfOwnNextTurn"},"when":{"wieldingProficientWeaponGroup":"Blade"}},{"type":"actionGrant","zone":"action","name":"Parry (Blade Focus)","summary":"Forgo one or more attacks during the Attack action: gain +1 AC per forgone attack until the start of your next turn.","durationSpec":{"anchor":"startOfOwnNextTurn"},"cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Blade"},"toggleEffect":{"name":"Blade Focus: Parry","note":"+1 AC per forgone attack until start of your next turn","maxValue":4}},{"type":"acBonus","valueFromEffect":"Blade Focus: Parry","label":"Blade Focus: Parry","when":{"activeEffect":"Blade Focus: Parry","wieldingProficientWeaponGroup":"Blade"}}]},{"name":"Carbine Focus","group":"Carbine","source":"Wretched Hives","description":"You've focused your combat training on carbine weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's damage rolls.\n- When you score a critical hit with the weapon, the next attack roll the target makes before the start of your next turn has disadvantage.\n\n- When you take the Attack action, you can choose to forgo one or more attacks to  **startle**. For each attack you forgo, you expend 1 ammunition and choose a creature that is no more than one size larger than you (your size or smaller if your weapon has the light property)  and is within your weapon's normal range. The creature must succeed on a Dexterity saving throw (DC = 8 + your bonus to attacks with the weapon) or become shocked until the start of your next turn.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"carbine","damageBonus":1,"when":{"proficient":true}},{"type":"contextualNote","surface":"attacks","title":"Carbine Focus (Critical Hit)","text":"On a critical hit with a proficient carbine weapon, the target's next attack roll before the start of your next turn has disadvantage.","durationSpec":{"anchor":"startOfOwnNextTurn"},"when":{"wieldingProficientWeaponGroup":"Carbine"}},{"type":"actionGrant","zone":"action","name":"Startle (Carbine Focus)","summary":"Forgo an attack and spend 1 ammo: target within normal range (≤ 1 size larger, or ≤ your size if light) makes a Dexterity save ({weaponAttackDC}) or becomes shocked until the start of your next turn.","durationSpec":{"anchor":"startOfOwnNextTurn"},"cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Carbine"}}]},{"name":"Crushing Weapon Focus","group":"Crushing","source":"Wretched Hives","description":"You've focused your combat training on crushing weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's damage rolls.\n- When you score a critical hit with the weapon, you add the attack's governing ability modifier twice, instead of once, to the attack's damage.\n- When you take the Attack action, you can choose to forgo one or more attacks to **shatter** the ground. For each attack you forgo, choose a separate 5-foot square within your weapon's reach to shatter. That square becomes difficult terrain until cleared. Each 5-foot-square portion of the area requires at least 1 minute to clear by hand. Additionally, each creature other than you in an affected square must make a Dexterity saving throw (DC = 8 + your bonus to attacks with the weapon). On a failed save, a creature takes damage equal to the attack's governing ability modifier.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"crushing","damageBonus":1,"when":{"proficient":true}},{"type":"critMod","weaponGroup":"crushing","doubleAbilityMod":true,"when":{"proficient":true}},{"type":"actionGrant","zone":"action","name":"Shatter (Crushing Weapon Focus)","summary":"Forgo an attack to shatter a separate 5-ft square within reach into difficult terrain (1 minute per square to clear by hand); creatures other than you in the square make a Dexterity save ({weaponAttackDC}) or take {weaponAbilityMod} damage.","durationSpec":{"anchor":"instant"},"cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Crushing"}}]},{"name":"Heavy Weapon Focus","group":"Heavy","source":"Wretched Hives","description":"You've focused your combat training on heavy weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's damage rolls.\n- When you score a critical hit with the weapon, you add the attack's governing ability modifier twice, instead of once, to the attack's damage.\n- When you take the Attack action, you can choose to forgo one or more attacks to **suppress**. For each attack you forgo, you expend ammunition equal to half your weapon's reload number (minimum of 2) and choose a 10-foot-cube area within your weapon's normal range. Each creature in the area that is no more than one size larger than you (your size or smaller if your weapon has the light property) must make a Wisdom saving throw (DC = 8 + your bonus to attacks with the weapon) or become frightened of you until the end of their next turn.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"heavy","damageBonus":1,"when":{"proficient":true}},{"type":"critMod","weaponGroup":"heavy","doubleAbilityMod":true,"when":{"proficient":true}},{"type":"actionGrant","zone":"action","name":"Suppress (Heavy Weapon Focus)","summary":"Forgo an attack and spend {weaponHalfReload}: creatures in a 10-ft cube within normal range (≤ 1 size larger, or ≤ your size if light) make a Wisdom save ({weaponAttackDC}) or become frightened of you until the end of their next turn.","durationSpec":{"anchor":"endOfTargetNextTurn"},"cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Heavy"}}]},{"name":"Polearm Focus","group":"Polearm","source":"Wretched Hives","description":"You've focused your combat training on polearm weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's damage rolls.\n- When you score a critical hit with the weapon, you can roll one additional weapon damage die.\n\n- When you take the Attack action, you can choose to forgo one of your attacks to **choke up**. If you do so, your reach increases by 5 feet until the start of your next turn.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"polearm","damageBonus":1,"when":{"proficient":true}},{"type":"critMod","weaponGroup":"polearm","brutalDice":1,"when":{"proficient":true}},{"type":"actionGrant","zone":"action","name":"Choke Up (Polearm Focus)","summary":"Forgo one attack during the Attack action: increase your reach by 5 feet until the start of your next turn.","durationSpec":{"anchor":"startOfOwnNextTurn"},"cadence":"oncePerTurn","when":{"wieldingProficientWeaponGroup":"Polearm"},"toggleEffect":{"name":"Polearm Focus: Choke Up","note":"+5 ft reach until start of your next turn"}},{"type":"weaponRule","kind":"reach","weaponGroup":"polearm","params":{"bonusFeet":5,"label":"Choke Up"},"when":{"activeEffect":"Polearm Focus: Choke Up","wieldingProficientWeaponGroup":"Polearm"}}]},{"name":"Rifle Focus","group":"Rifle","source":"Wretched Hives","description":"You've focused your combat training on rifle weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's damage rolls.\n- When you score a critical hit with the weapon, you can roll one additional weapon damage die.\n- When you take the Attack action, you can choose to forgo one or more attacks to  **scramble**. For each attack you forgo, you can move up to 10 feet without provoking opportunity attacks.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"rifle","damageBonus":1,"when":{"proficient":true}},{"type":"critMod","weaponGroup":"rifle","brutalDice":1,"when":{"proficient":true}},{"type":"actionGrant","zone":"action","name":"Scramble (Rifle Focus)","summary":"Forgo one or more attacks during the Attack action: move up to 10 feet per forgone attack without provoking opportunity attacks.","durationSpec":{"anchor":"instant"},"cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Rifle"}}]},{"name":"Sidearm Focus","group":"Sidearm","source":"Wretched Hives","description":"You've focused your combat training on sidearm weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's damage rolls.\n- When you score a critical hit with the weapon, the next attack roll made against the target before the start of your next turn has advantage.\n- When you take the Attack action, you can choose to forgo one or more attacks to **daze** a creature. For each attack you forgo, you expend 2 ammunition and choose a creature that is no more than one size larger than you (your size or smaller if your weapon has the light property), has a head, and is within your weapon's normal range. The creature must succeed on a Constitution saving throw (DC = 8 + your bonus to attacks with the weapon) or become incapacitated until the end of its next turn or until it takes damage, whichever happens first.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"sidearm","damageBonus":1,"when":{"proficient":true}},{"type":"contextualNote","surface":"attacks","title":"Sidearm Focus (Critical Hit)","text":"On a critical hit with a proficient sidearm weapon, the next attack roll made against the target before the start of your next turn has advantage.","durationSpec":{"anchor":"startOfOwnNextTurn"},"when":{"wieldingProficientWeaponGroup":"Sidearm"}},{"type":"actionGrant","zone":"action","name":"Daze (Sidearm Focus)","summary":"Forgo an attack and spend 2 ammo: target with a head within normal range (≤ 1 size larger, or ≤ your size if light) makes a Constitution save ({weaponAttackDC}) or becomes incapacitated until the end of its next turn or until it takes damage.","durationSpec":{"anchor":"endOfTargetNextTurn"},"cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Sidearm"}}]},{"name":"Trip Weapon Focus","group":"Trip","source":"Wretched Hives","description":"You've focused your combat training on trip weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's damage rolls.\n- When you score a critical hit with the weapon, the next attack roll made against the target before the start of your next turn has advantage.\n- When you take the Attack action, you can choose to forgo one or more attacks to **interrupt**. For each attack you forgo, one creature within your reach gains no benefit to armor class from its shield until the end of its next turn.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"trip","damageBonus":1,"when":{"proficient":true}},{"type":"contextualNote","surface":"attacks","title":"Trip Weapon Focus (Critical Hit)","text":"On a critical hit with a proficient trip weapon, the next attack roll made against the target before the start of your next turn has advantage.","durationSpec":{"anchor":"startOfOwnNextTurn"},"when":{"wieldingProficientWeaponGroup":"Trip"}},{"type":"actionGrant","zone":"action","name":"Interrupt (Trip Weapon Focus)","summary":"Forgo one or more attacks during the Attack action: one creature within reach gains no AC benefit from its shield until the end of its next turn.","durationSpec":{"anchor":"endOfTargetNextTurn"},"cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Trip"}}]}];
const SW5E_WEAPON_SUPREMACIES = [{"name":"Blade Supremacy","group":"Blade","source":"Wretched Hives","description":"You've specialized your combat training with blade weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's attack rolls.\n- Whenever you have advantage on an attack roll and hit and the lower of the two d20 rolls would also hit (or a creature has disadvantage on a saving throw and the higher of the two d20s would also fail), and the target is no more than one size larger than you (your size or smaller if your weapon has the light property), it must succeed on a Dexterity saving throw (DC = 8 + your bonus to attacks with the weapon) or gain 1 slowed level until the start of your next turn.\n- Your critical hit range increases by 1.\n- When you take the Attack action, you can choose to forgo one or more attacks to **parry**. For each attack you forgo, you gain a +1 bonus to AC until the start of your next turn. If you could already parry, instead you can do so as your bonus action.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"blade","attackBonus":1,"when":{"proficient":true}},{"type":"critMod","weaponGroup":"blade","critRangeDelta":1,"when":{"wieldingProficientWeaponGroup":"Blade"}},{"type":"contextualNote","surface":"attacks","title":"Blade Supremacy (Double Hit)","text":"On advantage double-hit or disadvantage double-fail (≤ 1 size larger, or ≤ your size if light), target makes a Dexterity save ({weaponAttackDC}) or gains 1 slowed level until the start of your next turn.","durationSpec":{"anchor":"startOfOwnNextTurn"},"when":{"wieldingProficientWeaponGroup":"Blade"}},{"type":"actionGrant","zone":"action","name":"Parry (Blade Supremacy)","summary":"Forgo one or more attacks during the Attack action: gain +1 AC per forgone attack until the start of your next turn (bonus action if you can already parry).","durationSpec":{"anchor":"startOfOwnNextTurn"},"cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Blade"},"toggleEffect":{"name":"Blade Focus: Parry","note":"+1 AC per forgone attack until start of your next turn","maxValue":4}},{"type":"actionUpgrade","targetAction":"parry","newZone":"bonus","summary":"Gain +1 AC until the start of your next turn (bonus action instead of forgoing an attack).","when":{"wieldingProficientWeaponGroup":"Blade"}},{"type":"acBonus","valueFromEffect":"Blade Focus: Parry","label":"Blade Focus: Parry","when":{"activeEffect":"Blade Focus: Parry","wieldingProficientWeaponGroup":"Blade"}}]},{"name":"Carbine Supremacy","group":"Carbine","source":"Wretched Hives","description":"You've specialized your combat training with carbine weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's attack rolls.\n- Whenever you have advantage on an attack roll and hit and the lower of the two d20 rolls would also hit (or a creature has disadvantage on a saving throw and the higher of the two d20s would also fail), and the target is no more than one size larger than you (your size or smaller if your weapon has the light property), it must succeed on a Dexterity saving throw (DC = 8 + your bonus to attacks with the weapon) or gain 1 slowed level until the start of your next turn.\n- You can wield this weapon in one hand. When you do so, you treat the weapon as if it would have the strength 11 property. If the weapon already has the strength property, its strength number increases by one step (from 11 to 13, 13 to 15, 15 to 17, 17 to 19, or 19 to 21). While wielding the weapon in one hand, you can't attack a target beyond the weapon's normal range.\n- When you take the Attack action, you can choose to forgo one or more attacks to  **startle**. For each attack you forgo, you expend 1 ammunition and choose a creature that is no more than one size larger than you (your size or smaller if your weapon has the light property)  and is within your weapon's normal range. The creature must succeed on a Dexterity saving throw (DC = 8 + your bonus to attacks with the weapon) or become shocked until the start of your next turn. If you could already startle, instead you can do so as your bonus action.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"carbine","attackBonus":1,"when":{"proficient":true}},{"type":"weaponRule","kind":"oneHanded","weaponGroup":"carbine","params":{"strengthBase":11,"strengthStepUp":1,"maxStrength":21,"maxRange":"normal"},"when":{"wieldingProficientWeaponGroup":"Carbine"}},{"type":"contextualNote","surface":"attacks","title":"Carbine Supremacy (Double Hit)","text":"On advantage double-hit or disadvantage double-fail (≤ 1 size larger, or ≤ your size if light), target makes a Dexterity save ({weaponAttackDC}) or gains 1 slowed level until the start of your next turn.","durationSpec":{"anchor":"startOfOwnNextTurn"},"when":{"wieldingProficientWeaponGroup":"Carbine"}},{"type":"actionGrant","zone":"action","name":"Startle (Carbine Supremacy)","summary":"Forgo an attack and spend 1 ammo: target within normal range (≤ 1 size larger, or ≤ your size if light) makes a Dexterity save ({weaponAttackDC}) or becomes shocked until the start of your next turn (bonus action if you can already startle).","durationSpec":{"anchor":"startOfOwnNextTurn"},"cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Carbine"}},{"type":"actionUpgrade","targetAction":"startle","newZone":"bonus","summary":"Spend 1 ammo: target within normal range (≤ 1 size larger, or ≤ your size if light) makes a Dexterity save ({weaponAttackDC}) or becomes shocked until the start of your next turn.","when":{"wieldingProficientWeaponGroup":"Carbine"}}]},{"name":"Crushing Weapon Supremacy","group":"Crushing","source":"Wretched Hives","description":"You've specialized your combat training with crushing weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's attack rolls.\n- Whenever you have advantage on an attack roll and hit and the lower of the two d20 rolls would also hit (or a creature has disadvantage on a saving throw and the higher of the two d20s would also fail), and the target is no more than one size larger than you (your size or smaller if your weapon has the light property), it must succeed on a Strength saving throw (DC = 8 + your bonus to attacks with the weapon) or it is pushed 5 feet in a direction of your choice.\n- Once per round, when you use your reaction to make a melee weapon attack, you have advantage on the attack roll.\n\n- When you take the Attack action, you can choose to forgo one or more attacks to **shatter** the ground. For each attack you forgo, choose a separate 5-foot square within your weapon's reach to shatter. That square becomes difficult terrain until cleared. Each 5-foot-square portion of the area requires at least 1 minute to clear by hand. Additionally, each creature other than you in an affected square must make a Dexterity saving throw (DC = 8 + your bonus to attacks with the weapon). On a failed save, a creature takes damage equal to the attack's governing ability modifier.  If you could already shatter, instead you can do so as your bonus action.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"crushing","attackBonus":1,"when":{"proficient":true}},{"type":"contextualNote","surface":"combat.reaction","title":"Crushing Weapon Supremacy","text":"Once per round, when you use your reaction to make a melee weapon attack, you have advantage on the attack roll.","cadence":"oncePerRound","when":{"wieldingProficientWeaponGroup":"Crushing"}},{"type":"contextualNote","surface":"attacks","title":"Crushing Weapon Supremacy (Double Hit)","text":"On advantage double-hit or disadvantage double-fail (≤ 1 size larger, or ≤ your size if light), target makes a Strength save ({weaponAttackDC}) or is pushed 5 feet in a direction of your choice.","when":{"wieldingProficientWeaponGroup":"Crushing"},"durationSpec":{"anchor":"instant"}},{"type":"actionGrant","zone":"action","name":"Shatter (Crushing Weapon Supremacy)","summary":"Forgo an attack: shatter a 5-foot square within reach (difficult terrain; 1 min to clear); other creatures in it make a Dexterity save ({weaponAttackDC}) or take {weaponAbilityMod} damage (bonus action if you can already shatter).","cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Crushing"},"durationSpec":{"anchor":"instant"}},{"type":"actionUpgrade","targetAction":"shatter","newZone":"bonus","summary":"Shatter a 5-foot square within reach (difficult terrain; 1 min to clear); other creatures in it make a Dexterity save ({weaponAttackDC}) or take {weaponAbilityMod} damage.","when":{"wieldingProficientWeaponGroup":"Crushing"}}]},{"name":"Heavy Weapon Supremacy","group":"Heavy","source":"Wretched Hives","description":"You've specialized your combat training with heavy weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's attack rolls.\n- Whenever you have advantage on an attack roll and hit and the lower of the two d20 rolls would also hit (or a creature has disadvantage on a saving throw and the higher of the two d20s would also fail), and the target is no more than one size larger than you (your size or smaller if your weapon has the light property), it must succeed on a Strength saving throw (DC = 8 + your bonus to attacks with the weapon) or it is pushed 5 feet in a direction of your choice.\n- When a creature rolls a 1 on the saving throw against one of these weapons, they treat the effect's damage as if it had rolled the maximum. If a creature would already treat the effect's damage as if it had rolled the maximum when it rolls a 1 on this weapon's saving throw, it instead does so on a roll of 1 or 2.\n- When you take the Attack action, you can choose to forgo one or more attacks to **suppress**. For each attack you forgo, you expend ammunition equal to half your weapon's reload number (minimum of 2) and choose a 10-foot-cube area within your weapon's normal range. Each creature in the area that is no more than one size larger than you (your size or smaller if your weapon has the light property) must make a Wisdom saving throw (DC = 8 + your bonus to attacks with the weapon) or become frightened of you until the end of their next turn. If you could already suppress, instead you can do so as your bonus action.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"heavy","attackBonus":1,"when":{"proficient":true}},{"type":"critMod","weaponGroup":"heavy","maxDamageOnSaveRoll":[1],"stackMaxDamageOnSaveRoll":[1,2],"when":{"wieldingProficientWeaponGroup":"Heavy"}},{"type":"contextualNote","surface":"attacks","title":"Heavy Weapon Supremacy (Double Hit)","text":"On advantage double-hit or disadvantage double-fail (≤ 1 size larger, or ≤ your size if light), target makes a Strength save ({weaponAttackDC}) or is pushed 5 feet in a direction of your choice.","when":{"wieldingProficientWeaponGroup":"Heavy"},"durationSpec":{"anchor":"instant"}},{"type":"actionGrant","zone":"action","name":"Suppress (Heavy Weapon Supremacy)","summary":"Forgo an attack and spend {weaponHalfReload}: 10-foot cube in normal range (≤ 1 size larger, or ≤ your size if light); creatures make a Wisdom save ({weaponAttackDC}) or become frightened of you until the end of their next turn (bonus action if you can already suppress).","durationSpec":{"anchor":"endOfTargetNextTurn"},"cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Heavy"}},{"type":"actionUpgrade","targetAction":"suppress","newZone":"bonus","summary":"Spend {weaponHalfReload}: creatures in a 10-foot cube within normal range (≤ 1 size larger, or ≤ your size if light) make a Wisdom save ({weaponAttackDC}) or become frightened of you until the end of their next turn.","when":{"wieldingProficientWeaponGroup":"Heavy"}}]},{"name":"Polearm Supremacy","group":"Polearm","source":"Wretched Hives","description":"You've specialized your combat training with polearm weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's attack rolls.\n- Whenever you have advantage on an attack roll and hit and the lower of the two d20 rolls would also hit (or a creature has disadvantage on a saving throw and the higher of the two d20s would also fail), and the target is no more than one size larger than you (your size or smaller if your weapon has the light property), you have advantage on the weapon's damage roll.\n- When you make an ability check or saving throw against an effect that would shove or trip you, you can treat a d20 roll of below half your level (rounded up) as half your level.\n- When you take the Attack action, you can choose to forgo one of your attacks to **choke up**. If you do so, your reach increases by 5 feet until the start of your next turn. If you could already choke up, instead you can do so as your bonus action.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"polearm","attackBonus":1,"when":{"proficient":true}},{"type":"rollFloor","scope":"d20","minRoll":"ceil(level/2)","skills":["Athletics","Acrobatics"],"condition":"treat d20 below {ceilHalfLevel} as {ceilHalfLevel} on ability checks or saving throws against shove or trip","when":{"wieldingProficientWeaponGroup":"Polearm"}},{"type":"contextualNote","surface":"saves","title":"Polearm Supremacy (Steady Footing)","text":"On ability checks or saving throws against shove or trip, treat a d20 roll below {ceilHalfLevel} as {ceilHalfLevel}.","when":{"wieldingProficientWeaponGroup":"Polearm"}},{"type":"contextualNote","surface":"attacks","title":"Polearm Supremacy (Double Hit)","text":"On advantage double-hit or disadvantage double-fail (≤ 1 size larger, or ≤ your size if light), gain advantage on the weapon's damage roll.","when":{"wieldingProficientWeaponGroup":"Polearm"},"durationSpec":{"anchor":"instant"}},{"type":"actionGrant","zone":"action","name":"Choke Up (Polearm Supremacy)","summary":"Forgo one attack during the Attack action: increase your reach by 5 feet until the start of your next turn (bonus action if you can already choke up).","durationSpec":{"anchor":"startOfOwnNextTurn"},"cadence":"oncePerTurn","when":{"wieldingProficientWeaponGroup":"Polearm"},"toggleEffect":{"name":"Polearm Focus: Choke Up","note":"+5 ft reach until start of your next turn"}},{"type":"actionUpgrade","targetAction":"choke up","newZone":"bonus","summary":"Increase your reach by 5 feet until the start of your next turn.","when":{"wieldingProficientWeaponGroup":"Polearm"}},{"type":"weaponRule","kind":"reach","weaponGroup":"polearm","params":{"bonusFeet":5,"label":"Choke Up"},"when":{"activeEffect":"Polearm Focus: Choke Up","wieldingProficientWeaponGroup":"Polearm"}}]},{"name":"Rifle Supremacy","group":"Rifle","source":"Wretched Hives","description":"You've specialized your combat training with rifle weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's attack rolls.\n- Whenever you have advantage on an attack roll and hit and the lower of the two d20 rolls would also hit (or a creature has disadvantage on a saving throw and the higher of the two d20s would also fail), and the target is no more than one size larger than you (your size or smaller if your weapon has the light property), you have advantage on the weapon's damage roll.\n- Your ranged weapon attacks reduce partial cover by one step (from three-quarters to half or half to one-quarter) against targets within 30 feet of you. If the target has one-quarter cover, you ignore it entirely.\n- When you take the Attack action, you can choose to forgo one or more attacks to  **scramble**. For each attack you forgo, you can move up to 10 feet without provoking opportunity attacks. If you could already scramble, instead you can do so as your bonus action.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"rifle","attackBonus":1,"when":{"proficient":true}},{"type":"combatTrait","kind":"coverReduction","value":1,"note":"Ranged rifle attacks within 30 feet reduce partial cover by 1 step (¾ → ½, ½ → ¼) and ignore one-quarter cover.","when":{"wieldingProficientWeaponGroup":"Rifle"},"range":"<=30 ft","weaponGroup":"rifle"},{"type":"contextualNote","surface":"attacks","title":"Rifle Supremacy (Double Hit)","text":"On advantage double-hit or disadvantage double-fail (≤ 1 size larger, or ≤ your size if light), gain advantage on the weapon's damage roll.","when":{"wieldingProficientWeaponGroup":"Rifle"},"durationSpec":{"anchor":"instant"}},{"type":"actionGrant","zone":"action","name":"Scramble (Rifle Supremacy)","summary":"Forgo one or more attacks during the Attack action: move up to 10 feet per forgone attack without provoking opportunity attacks (bonus action if you can already scramble).","cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Rifle"},"durationSpec":{"anchor":"instant"}},{"type":"actionUpgrade","targetAction":"scramble","newZone":"bonus","summary":"Move up to 10 feet without provoking opportunity attacks.","when":{"wieldingProficientWeaponGroup":"Rifle"}}]},{"name":"Sidearm Supremacy","group":"Sidearm","source":"Wretched Hives","description":"You've specialized your combat training with sidearm weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's attack rolls.\n- Whenever you have advantage on an attack roll and hit and the lower of the two d20 rolls would also hit (or a creature has disadvantage on a saving throw and the higher of the two d20s would also fail), and the target is no more than one size larger than you (your size or smaller if your weapon has the light property), it must succeed on a Strength saving throw (DC = 8 + your bonus to attacks with the weapon) or it drops an object of your choice. If you have a free hand and the object is within your reach, you catch the object. Otherwise, it lands at your feet.\n- You can now reload these weapons using your reaction or object interaction, instead of just your action or bonus action. You must have one free hand to reload.\n- When you take the Attack action, you can choose to forgo one or more attacks to **daze** a creature. For each attack you forgo, you expend 2 ammunition and choose a creature that is no more than one size larger than you (your size or smaller if your weapon has the light property), has a head, and is within your weapon's normal range. The creature must succeed on a Constitution saving throw (DC = 8 + your bonus to attacks with the weapon) or become incapacitated until the end of its next turn or until it takes damage, whichever happens first.  If you could already daze, instead you can do so as your bonus action.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"sidearm","attackBonus":1,"when":{"proficient":true}},{"type":"actionGrant","zone":"reaction","name":"Fast Reload (Sidearm Supremacy)","summary":"Reload a proficient sidearm using your reaction or object interaction instead of your action or bonus action (requires one free hand).","cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Sidearm"},"reactionKind":"standard"},{"type":"contextualNote","surface":"attacks","title":"Sidearm Supremacy (Double Hit)","text":"On advantage double-hit or disadvantage double-fail (≤ 1 size larger, or ≤ your size if light), target makes a Strength save ({weaponAttackDC}) or drops a chosen object (caught if free hand within reach; otherwise lands at your feet).","when":{"wieldingProficientWeaponGroup":"Sidearm"},"durationSpec":{"anchor":"instant"}},{"type":"actionGrant","zone":"action","name":"Daze (Sidearm Supremacy)","summary":"Forgo an attack and spend 2 ammo: target with a head within normal range (≤ 1 size larger, or ≤ your size if light) makes a Constitution save ({weaponAttackDC}) or becomes incapacitated until the end of its next turn or until it takes damage (bonus action if you can already daze).","durationSpec":{"anchor":"endOfTargetNextTurn"},"cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Sidearm"}},{"type":"actionUpgrade","targetAction":"daze","newZone":"bonus","summary":"Spend 2 ammo: target with a head within normal range (≤ 1 size larger, or ≤ your size if light) makes a Constitution save ({weaponAttackDC}) or becomes incapacitated until the end of its next turn or until it takes damage.","when":{"wieldingProficientWeaponGroup":"Sidearm"}}]},{"name":"Trip Weapon Supremacy","group":"Trip","source":"Wretched Hives","description":"You've specialized your combat training with trip weapons. You gain the following benefits while wielding any of these weapons, if you are proficient with it:\n- You gain a +1 bonus to the weapon's attack rolls.\n- Whenever you have advantage on an attack roll and hit and the lower of the two d20 rolls would also hit (or a creature has disadvantage on a saving throw and the higher of the two d20s would also fail), and the target is no more than one size larger than you (your size or smaller if your weapon has the light property), it must succeed on a Strength saving throw (DC = 8 + your bonus to attacks with the weapon) or it drops an object of your choice. If you have a free hand, you catch the weapon. Otherwise, it lands at your feet. \n- You have advantage on Strength (Athletics) checks and attack rolls made to trip a creature.\n- When you take the Attack action, you can choose to forgo one or more attacks to **interrupt**. For each attack you forgo, one creature within your reach gains no benefit to armor class from its shield until the end of its next turn. If you could already interrupt, instead you can do so as your bonus action.","effects":[{"type":"attackDamageMod","scope":"weaponGroup","weaponGroup":"trip","attackBonus":1,"when":{"proficient":true}},{"type":"conditionalCheckMod","skills":["Athletics"],"mode":"advantage","condition":"tripping a creature","when":{"wieldingProficientWeaponGroup":"Trip"}},{"type":"contextualNote","surface":"attacks","title":"Trip Weapon Supremacy (Trip)","text":"Advantage on attack rolls made to trip a creature.","when":{"wieldingProficientWeaponGroup":"Trip"}},{"type":"contextualNote","surface":"attacks","title":"Trip Weapon Supremacy (Double Hit)","text":"On advantage double-hit or disadvantage double-fail (≤ 1 size larger, or ≤ your size if light), target makes a Strength save ({weaponAttackDC}) or drops a chosen object (caught if free hand; otherwise lands at your feet).","when":{"wieldingProficientWeaponGroup":"Trip"},"durationSpec":{"anchor":"instant"}},{"type":"actionGrant","zone":"action","name":"Interrupt (Trip Weapon Supremacy)","summary":"Forgo an attack: one creature within your reach gains no AC benefit from its shield until the end of its next turn (bonus action if you can already interrupt).","durationSpec":{"anchor":"endOfTargetNextTurn"},"cadence":"unlimited","when":{"wieldingProficientWeaponGroup":"Trip"}},{"type":"actionUpgrade","targetAction":"interrupt","newZone":"bonus","summary":"One creature within your reach gains no AC benefit from its shield until the end of its next turn.","when":{"wieldingProficientWeaponGroup":"Trip"}}]}];
